/**
 * Deterministic QA Heuristic Engine for TestGenius AI
 *
 * Provides rule-based test case generation, static failure-mode detection,
 * and Playwright Python test script generation without requiring an external AI API.
 * All results are clearly labeled as generated by the Deterministic QA Engine.
 */

import {
  TestCase,
  BugAnalysisItem,
  GeneratedScript,
  GenerateTestsPayload,
  AnalyzeBugsPayload,
  GenerateScriptPayload,
  TestCategory,
  TestPriority,
} from '../types';

interface DetectedField {
  name: string;
  id: string;
  type: string;
  label: string;
  required: boolean;
  minlength?: number;
  maxlength?: number;
  pattern?: string;
}

/**
 * Extracts form field metadata from supplied HTML or component code
 */
function extractFieldsFromHtml(html: string): DetectedField[] {
  const fields: DetectedField[] = [];
  if (!html) return fields;

  // Simple, safe regex extraction without executing untrusted code
  const inputRegex = /<input\b([^>]*)>/gi;
  let match: RegExpExecArray | null;

  while ((match = inputRegex.exec(html)) !== null) {
    const attrs = match[1];
    const nameMatch = attrs.match(/name=["']([^"']+)["']/i);
    const idMatch = attrs.match(/id=["']([^"']+)["']/i);
    const typeMatch = attrs.match(/type=["']([^"']+)["']/i);
    const reqMatch = /\brequired\b/i.test(attrs);
    const minMatch = attrs.match(/minlength=["'](\d+)["']/i);
    const maxMatch = attrs.match(/maxlength=["'](\d+)["']/i);
    const patternMatch = attrs.match(/pattern=["']([^"']+)["']/i);

    const type = typeMatch ? typeMatch[1].toLowerCase() : 'text';
    if (type === 'hidden') continue; // Skip hidden tokens for field list

    const id = idMatch ? idMatch[1] : '';
    const name = nameMatch ? nameMatch[1] : id || `field_${fields.length + 1}`;

    // Look for associated label in HTML
    let label = name.replace(/[-_]/g, ' ');
    if (id) {
      const labelRegex = new RegExp(
        `<label[^>]*for=["']${id}["'][^>]*>([\\s\\S]*?)<\\/label>`,
        'i'
      );
      const labelMatch = html.match(labelRegex);
      if (labelMatch) {
        label = labelMatch[1].replace(/<[^>]+>/g, '').trim();
      }
    }

    fields.push({
      name,
      id: id || name,
      type,
      label: label.charAt(0).toUpperCase() + label.slice(1),
      required: reqMatch,
      minlength: minMatch ? parseInt(minMatch[1], 10) : undefined,
      maxlength: maxMatch ? parseInt(maxMatch[1], 10) : undefined,
      pattern: patternMatch ? patternMatch[1] : undefined,
    });
  }

  // Look for textareas
  const textareaRegex = /<textarea\b([^>]*)>/gi;
  while ((match = textareaRegex.exec(html)) !== null) {
    const attrs = match[1];
    const nameMatch = attrs.match(/name=["']([^"']+)["']/i);
    const idMatch = attrs.match(/id=["']([^"']+)["']/i);
    const id = idMatch ? idMatch[1] : '';
    const name = nameMatch ? nameMatch[1] : id || `textarea_${fields.length + 1}`;
    fields.push({
      name,
      id: id || name,
      type: 'textarea',
      label: name.replace(/[-_]/g, ' '),
      required: /\brequired\b/i.test(attrs),
    });
  }

  return fields;
}

/**
 * Generate structured test cases using deterministic QA heuristic rules
 */
export function generateDeterministicTestCases(
  payload: GenerateTestsPayload
): TestCase[] {
  const {
    projectId,
    featureDescription,
    componentCode = '',
    stagingUrl = 'https://example.com/app',
    testTypes = [
      'Functional',
      'Validation',
      'Negative',
      'Boundary',
      'Accessibility',
      'Security',
    ],
    priorityFilter = 'All',
    targetBrowser = 'Chromium',
  } = payload;

  const descLower = featureDescription.toLowerCase();
  const fields = extractFieldsFromHtml(componentCode);
  const isAuth =
    descLower.includes('login') ||
    descLower.includes('auth') ||
    descLower.includes('password') ||
    descLower.includes('signin') ||
    descLower.includes('sign in');
  const isCheckout =
    descLower.includes('checkout') ||
    descLower.includes('pay') ||
    descLower.includes('card') ||
    descLower.includes('billing');
  const isUpload =
    descLower.includes('upload') ||
    descLower.includes('file') ||
    descLower.includes('avatar') ||
    descLower.includes('attachment');

  const testCases: TestCase[] = [];
  const now = new Date().toISOString();
  let count = 1;

  const getNextId = (catPrefix: string) => {
    const pad = String(count++).padStart(3, '0');
    return `TG-${catPrefix}-${pad}`;
  };

  // 1. FUNCTIONAL / HAPPY PATH TEST CASES
  if (testTypes.includes('Functional')) {
    if (isAuth) {
      testCases.push({
        id: getNextId('FUNC'),
        projectId,
        title: 'Successful Authentication with Valid Credentials',
        objective:
          'Verify user can log into account with verified email address and correct password.',
        category: 'Functional',
        priority: 'Critical',
        preconditions: [
          `Navigate to login page at ${stagingUrl}`,
          'Test user account exists and is in ACTIVE status',
        ],
        steps: [
          'Locate email input field and enter valid registered email address.',
          'Locate password input field and enter correct active password.',
          'Optionally toggle "Remember Me" checkbox to true.',
          'Click the "Sign In" / submit button.',
          'Wait for network response and redirect event.',
        ],
        testData: 'Email: qa.testuser@example.com | Password: ValidPassword123!',
        expectedResult:
          'User is authenticated successfully, session token or auth cookie is established, and redirected to dashboard without console errors.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });

      testCases.push({
        id: getNextId('FUNC'),
        projectId,
        title: 'Show / Hide Password Visibility Toggle Functionality',
        objective:
          'Verify user can toggle password visibility mask to inspect typed characters.',
        category: 'Functional',
        priority: 'Medium',
        preconditions: [`Open page at ${stagingUrl}`],
        steps: [
          'Click password input field and type secret password string.',
          'Observe input attribute type="password" (characters masked).',
          'Click the password visibility toggle icon button.',
          'Verify input attribute switches to type="text" and plain text is displayed.',
          'Click toggle button once more to revert to masked state.',
        ],
        testData: 'Input: MySecretP@ss2026',
        expectedResult:
          'Field type alternates between "password" and "text" without altering the input value.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    } else if (isCheckout) {
      testCases.push({
        id: getNextId('FUNC'),
        projectId,
        title: 'Successful Order Checkout with Valid Payment Card',
        objective:
          'Verify checkout form processes valid card payment and renders order confirmation receipt.',
        category: 'Functional',
        priority: 'Critical',
        preconditions: [
          `Navigate to checkout modal at ${stagingUrl}`,
          'Cart contains at least one active order item',
        ],
        steps: [
          'Enter cardholder full name into "Cardholder Name" input.',
          'Enter 16-digit test Visa card number into "Card Number" field.',
          'Enter valid future expiration date (e.g. 12/28).',
          'Enter valid 3-digit security code (CVV).',
          'Click the primary "Pay Now" action button.',
          'Wait for payment gateway webhook / token response.',
        ],
        testData:
          'Name: Jane Tester | Card: 4242 4242 4242 4242 | Expiry: 12/28 | CVV: 123',
        expectedResult:
          'Payment token is generated, form transitions to processing state, order confirmation is displayed with receipt ID.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    } else {
      testCases.push({
        id: getNextId('FUNC'),
        projectId,
        title: 'Standard Happy Path Form Submission with Complete Data',
        objective: `Verify that all fields can be filled with standard valid input and form completes successfully based on: ${featureDescription.slice(0, 80)}...`,
        category: 'Functional',
        priority: 'High',
        preconditions: [`User is on target view at ${stagingUrl}`],
        steps: [
          'Fill all visible input elements with valid formatted test data.',
          'Trigger change/blur events to verify no spurious validation errors appear.',
          'Click primary submission button.',
          'Verify submission loading indicator displays.',
          'Observe success response status code (HTTP 200/201).',
        ],
        testData:
          fields.length > 0
            ? fields.map((f) => `${f.label}: valid_${f.type}_val`).join(' | ')
            : 'Default valid inputs across all form components',
        expectedResult:
          'Form successfully saves, feedback banner or toast confirms success, and no uncaught exceptions are logged.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    }
  }

  // 2. VALIDATION TEST CASES
  if (testTypes.includes('Validation')) {
    testCases.push({
      id: getNextId('VAL'),
      projectId,
      title: 'Blank Mandatory Field Submission Handling',
      objective:
        'Verify form inhibits submission and highlights mandatory fields when user clicks submit with blank inputs.',
      category: 'Validation',
      priority: 'High',
      preconditions: [`User navigates to ${stagingUrl} with pristine form state`],
      steps: [
        'Do not enter any values into the required input fields.',
        'Click the submit button directly.',
        'Inspect DOM for validation messages and red outline highlight classes.',
        'Verify network tab to ensure no POST/PUT request is dispatched.',
      ],
      testData: 'All inputs empty strings: ""',
      expectedResult:
        'Client-side validation intercepts submission. Accessible inline errors (e.g. role="alert") highlight required fields.',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });

    if (isAuth || fields.some((f) => f.type === 'email')) {
      testCases.push({
        id: getNextId('VAL'),
        projectId,
        title: 'Email Format Validation (Missing @ or Domain)',
        objective:
          'Verify rejection of malformed email addresses that fail standard RFC regex standards.',
        category: 'Validation',
        priority: 'High',
        preconditions: [`Form open at ${stagingUrl}`],
        steps: [
          'Input "testuser-without-at-sign" into email field.',
          'Blur the field or click submit.',
          'Observe error notification.',
          'Replace input with "testuser@domain" (missing top level domain).',
          'Attempt submission again.',
        ],
        testData:
          'Inputs: "plainaddress", "missing@domain", "#@%^%#$@#$@#.com"',
        expectedResult:
          'Form rejects malformed email strings and displays "Please enter a valid email address".',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    }

    if (isAuth || fields.some((f) => f.type === 'password')) {
      testCases.push({
        id: getNextId('VAL'),
        projectId,
        title: 'Password Complexity and Minimum Length Constraint',
        objective:
          'Verify password validation enforces minimum length threshold (e.g. 8 characters).',
        category: 'Validation',
        priority: 'High',
        preconditions: [`Pristine form at ${stagingUrl}`],
        steps: [
          'Input a valid email address.',
          'Input 5 characters "12345" into password field (below minimum required 8).',
          'Click submit or trigger blur.',
          'Verify feedback error indicates minimum length required.',
        ],
        testData: 'Password: "short"',
        expectedResult:
          'Validation error "Password must be at least 8 characters" is rendered; form prevents API call.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    }
  }

  // 3. NEGATIVE TEST CASES
  if (testTypes.includes('Negative')) {
    if (isAuth) {
      testCases.push({
        id: getNextId('NEG'),
        projectId,
        title: 'Invalid Password for Existing Account (HTTP 401)',
        objective:
          'Verify application handles incorrect password gracefully without revealing user enumeration details.',
        category: 'Negative',
        priority: 'High',
        preconditions: [
          `Navigate to ${stagingUrl}`,
          'Target user email exists in database',
        ],
        steps: [
          'Enter registered email: qa.existing@example.com.',
          'Enter incorrect password: WrongPassword999#.',
          'Click Sign In.',
          'Observe network response and UI alert.',
        ],
        testData: 'Email: qa.existing@example.com | Password: WrongPassword999#',
        expectedResult:
          'Server returns 401 Unauthorized. UI displays generic error message: "Invalid email or password". Password field retains focus.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    }

    testCases.push({
      id: getNextId('NEG'),
      projectId,
      title: 'Server Error (500 Internal Server Error) UI Recovery',
      objective:
        'Verify UI remains interactive and informs the user gracefully when backend returns HTTP 500.',
      category: 'Negative',
      priority: 'Medium',
      preconditions: [
        `Navigate to ${stagingUrl}`,
        'Mock or trigger backend API outage simulation (HTTP 500)',
      ],
      steps: [
        'Complete form with standard valid inputs.',
        'Submit the form.',
        'Simulate backend 500 error response.',
        'Verify button re-enables and loading spinner clears.',
        'Verify clear user-facing error message appears.',
      ],
      testData: 'HTTP 500 Internal Server Error simulation',
      expectedResult:
        'UI does not freeze or crash with blank white screen. Reusable error toast displays "Something went wrong. Please try again later".',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });
  }

  // 4. BOUNDARY TEST CASES
  if (testTypes.includes('Boundary')) {
    testCases.push({
      id: getNextId('BOUND'),
      projectId,
      title: 'Maximum Character Length Upper Limit Stress Test',
      objective:
        'Verify inputs correctly handle maximum character length boundary (e.g. 255 chars or field limit) without UI overflow.',
      category: 'Boundary',
      priority: 'Medium',
      preconditions: [`Navigate to ${stagingUrl}`],
      steps: [
        'Generate an alphanumeric string exactly at the field maximum boundary (e.g. 64 or 255 chars).',
        'Paste string into input field.',
        'Verify characters are accepted and layout does not break.',
        'Attempt to append 1 additional character (Max + 1).',
        'Verify HTML maxlength or client script truncates or flags error.',
      ],
      testData: 'String of 255 repeating characters: "A".repeat(255)',
      expectedResult:
        'Input field respects maxlength restriction without text overflowing the bounding container or causing database truncation errors.',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });

    testCases.push({
      id: getNextId('BOUND'),
      projectId,
      title: 'Whitespace-Only and Leading/Trailing Spaces Input Handling',
      objective:
        'Verify application trims whitespace or rejects values composed entirely of space characters.',
      category: 'Boundary',
      priority: 'Low',
      preconditions: [`Open page at ${stagingUrl}`],
      steps: [
        'Input only space characters "    " into required text fields.',
        'Attempt to click submit button.',
        'Verify whether form treats whitespace as an empty field.',
        'Enter valid input with leading and trailing spaces: "   validUser   ".',
        'Submit and inspect payload.',
      ],
      testData: 'Values: "   " and "   validUser   "',
      expectedResult:
        'Whitespace-only is rejected as empty. Leading and trailing whitespaces are automatically sanitized / trimmed before submission.',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });
  }

  // 5. ACCESSIBILITY TEST CASES
  if (testTypes.includes('Accessibility')) {
    testCases.push({
      id: getNextId('A11Y'),
      projectId,
      title: 'Full Keyboard Navigation and Tabindex Sequencing',
      objective:
        'Verify complete user workflow can be accomplished without using a mouse or pointing device (WCAG 2.1 - 2.1.1).',
      category: 'Accessibility',
      priority: 'High',
      preconditions: [
        `Navigate to ${stagingUrl}`,
        'Initial focus set to top of document',
      ],
      steps: [
        'Press "Tab" repeatedly to advance through all interactive elements.',
        'Verify visible focus ring indicator (outline) is present on each focused control.',
        'Verify tab order follows natural reading order (top-to-bottom, left-to-right).',
        'Press "Shift+Tab" to confirm backward navigation works without focus trap.',
        'When on the submit button or form input, press "Enter" to trigger submission.',
      ],
      testData: 'Keyboard keys: Tab, Shift+Tab, Enter, Space',
      expectedResult:
        'All interactive form controls are reachable via keyboard, have high-contrast focus rings, and no keyboard traps exist.',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });

    testCases.push({
      id: getNextId('A11Y'),
      projectId,
      title: 'Form Label Association and Screen Reader ARIA Compliance',
      objective:
        'Verify all form inputs possess explicit programmatic labels via `<label for="...">` or `aria-label` attributes.',
      category: 'Accessibility',
      priority: 'Medium',
      preconditions: [`Inspect DOM elements at ${stagingUrl}`],
      steps: [
        'Audit each `<input>`, `<select>`, `<textarea>` element for valid `id`.',
        'Verify corresponding `<label>` element has matching `for` attribute.',
        'Check toggle icon buttons (e.g. show password) have `aria-label` or `<span class="sr-only">`.',
        'Verify error message containers include `role="alert"` or `aria-live="polite"`.',
      ],
      testData: 'Screen Reader DOM inspection (NVDA/VoiceOver compliant)',
      expectedResult:
        '100% of form inputs have associated labels. Clicking on label text moves focus to the input. Error states are read automatically.',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });
  }

  // 6. SECURITY TEST CASES
  if (testTypes.includes('Security')) {
    testCases.push({
      id: getNextId('SEC'),
      projectId,
      title: 'Cross-Site Scripting (XSS) Vector Injection Prevention',
      objective:
        'Verify application neutralizes XSS payloads and properly HTML-escapes input during client rendering.',
      category: 'Security',
      priority: 'Critical',
      preconditions: [`User open at ${stagingUrl}`],
      steps: [
        'Input malicious XSS payload into text fields: `<script>alert("XSS")</script>`.',
        'Input HTML tag breakout payload: `"><img src=x onerror=alert(1)>`.',
        'Submit form or trigger client-side preview.',
        'Inspect rendered DOM tree and JavaScript console.',
      ],
      testData:
        'Payloads: `<script>alert("XSS")</script>`, `"><svg/onload=alert(document.domain)>`',
      expectedResult:
        'Payload is treated as pure literal text, characters `<` and `>` are encoded as `&lt;` and `&gt;`. No script execution occurs.',
      status: 'Not Run',
      generatedBy: 'heuristic-engine',
      targetBrowser,
      createdAt: now,
      updatedAt: now,
    });

    if (isAuth) {
      testCases.push({
        id: getNextId('SEC'),
        projectId,
        title: 'Brute-Force Rate Limiting and Account Lockout Verification',
        objective:
          'Verify protection against credential stuffing attacks by locking or throttling repeated failed attempts.',
        category: 'Security',
        priority: 'High',
        preconditions: [
          `Navigate to ${stagingUrl}`,
          'Test user account created',
        ],
        steps: [
          'Attempt 5 consecutive login submissions with wrong passwords in rapid succession.',
          'On the 6th attempt, submit credentials again.',
          'Inspect response headers and status codes.',
        ],
        testData: '5 rapid failed login attempts with invalid credentials',
        expectedResult:
          'Application returns HTTP 429 Too Many Requests or requires CAPTCHA verification; temporarily locks account or throttles response.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });

      testCases.push({
        id: getNextId('SEC'),
        projectId,
        title: 'Sensitive Credential Masking and Autocomplete Attribute Audit',
        objective:
          'Verify password field prevents cleartext leakage in memory, browser history, and devtools.',
        category: 'Security',
        priority: 'Medium',
        preconditions: [`Inspect DOM and Network tab at ${stagingUrl}`],
        steps: [
          'Verify password field uses type="password".',
          'Inspect network request to ensure credentials are transmitted in HTTP POST request body over HTTPS, never in URL query params.',
          'Verify autocomplete="current-password" or "new-password" is used.',
        ],
        testData: 'Password field security attributes check',
        expectedResult:
          'Credentials remain masked, are never logged to console or URL query string, and transmitted strictly over encrypted HTTPS POST.',
        status: 'Not Run',
        generatedBy: 'heuristic-engine',
        targetBrowser,
        createdAt: now,
        updatedAt: now,
      });
    }
  }

  // Filter by priority if specified
  if (priorityFilter !== 'All') {
    return testCases.filter((tc) => tc.priority === priorityFilter);
  }

  return testCases;
}

/**
 * Perform static QA heuristic analysis to detect plausible failure modes and bugs
 */
export function analyzeDeterministicBugs(
  payload: AnalyzeBugsPayload
): BugAnalysisItem[] {
  const {
    projectId,
    featureDescription,
    componentCode = '',
    stagingUrl = 'https://example.com/app',
  } = payload;

  const bugs: BugAnalysisItem[] = [];
  const now = new Date().toISOString();
  let count = 1;

  const getNextId = (prefix: string) => {
    return `BUG-STATIC-${prefix}-${String(count++).padStart(3, '0')}`;
  };

  const code = componentCode;
  const desc = featureDescription.toLowerCase();

  // Check 1: Missing or Incomplete CSRF Protection
  const hasCsrf =
    code.includes('csrf') ||
    code.includes('csrf_token') ||
    code.includes('xsrf') ||
    desc.includes('csrf');
  if (!hasCsrf) {
    bugs.push({
      id: getNextId('CSRF'),
      projectId,
      title: 'Missing Cross-Site Request Forgery (CSRF) Token in Form Payload',
      severity: 'High',
      category: 'Security Concern',
      affectedFeature: 'Form Submission / State Alteration',
      explanation:
        'Static code inspection indicates the form submits state-changing data without an embedded CSRF token or anti-forgery token header. If the application relies solely on standard session cookies without SameSite=Strict cookies or token validation, an attacker could forge requests from malicious third-party origins.',
      reproductionSteps: [
        'Inspect the HTML <form> markup and associated JavaScript fetch headers.',
        'Observe absence of hidden <input name="csrf_token"> or X-CSRF-Token request header.',
        'Craft a cross-origin HTML page that submits POST request to the API endpoint with victim credentials.',
      ],
      expectedBehavior:
        'All state-changing POST/PUT/DELETE forms must transmit a cryptographically unpredictable anti-CSRF token verified server-side.',
      actualBehavior:
        '(Inferred from static code inspection - unverified on live servers) Form lacks explicit CSRF token input or token header binding.',
      suggestedFix:
        'Inject a server-generated CSRF token into a hidden input or attach an X-CSRF-Token header in API requests, combined with SameSite=Lax/Strict cookie flags.',
      suggestedCodeSnippet: `<input type="hidden" name="csrf_token" value="{{ csrf_token }}" />`,
      isStaticInference: true,
      createdAt: now,
    });
  }

  // Check 2: Double-Click / Race Condition on Form Submission
  const hasDisabledSubmit =
    code.includes('disabled') ||
    code.includes('isSubmitting') ||
    code.includes('loading');
  if (!hasDisabledSubmit) {
    bugs.push({
      id: getNextId('RACE'),
      projectId,
      title: 'Potential Double-Submission / Race Condition on Submit Button',
      severity: 'Medium',
      category: 'Failure Mode',
      affectedFeature: 'Submit Button / Network Handler',
      explanation:
        'The submit button does not appear to disable or show a busy state upon initial click. Users with slow network latency or those who double-click the button may dispatch duplicate requests, resulting in duplicate records, multiple charges, or race conditions.',
      reproductionSteps: [
        'Open the form on a throttled 3G network connection.',
        'Fill in the required inputs.',
        'Rapidly double-click the primary submit button.',
        'Check network logs for multiple concurrent HTTP requests.',
      ],
      expectedBehavior:
        'Button should immediately enter a disabled loading state upon first click and ignore subsequent trigger clicks until the request resolves.',
      actualBehavior:
        '(Inferred from static code inspection - unverified on live servers) Button does not declare disabled state or loading debounce guard.',
      suggestedFix:
        'Add a loading state to disable the submit button and display a loading spinner while the API call is in flight.',
      suggestedCodeSnippet: `<button type="submit" disabled={isSubmitting} class="disabled:opacity-50 disabled:cursor-not-allowed">
  {isSubmitting ? "Processing..." : "Submit"}
</button>`,
      isStaticInference: true,
      createdAt: now,
    });
  }

  // Check 3: Missing ARIA Live Announcement for Asynchronous Errors
  const hasAriaAlert =
    code.includes('role="alert"') ||
    code.includes("role='alert'") ||
    code.includes('aria-live') ||
    code.includes('aria-describedby');
  if (!hasAriaAlert) {
    bugs.push({
      id: getNextId('A11Y'),
      projectId,
      title: 'Missing ARIA Alert Announcements for Dynamic Validation Errors',
      severity: 'Medium',
      category: 'Accessibility Issue',
      affectedFeature: 'Error Message Feedback',
      explanation:
        'When validation fails or server errors occur, visual error text may appear on screen, but without role="alert" or aria-live="polite", assistive technologies (screen readers like NVDA/VoiceOver) will not announce the error to visually impaired users.',
      reproductionSteps: [
        'Activate screen reader (VoiceOver or NVDA).',
        'Trigger a validation failure by submitting an empty or invalid form.',
        'Listen for screen reader audio feedback.',
      ],
      expectedBehavior:
        'Screen readers should automatically announce the error message upon appearance via ARIA live regions.',
      actualBehavior:
        '(Inferred from static code inspection - unverified on live servers) Error containers lack role="alert" or aria-live attributes.',
      suggestedFix:
        'Add role="alert" or aria-live="polite" to all dynamic validation error messages, and link inputs to their error message using aria-describedby.',
      suggestedCodeSnippet: `<span id="email-error" role="alert" aria-live="polite" class="text-red-500 text-xs">
  Please enter a valid email address
</span>`,
      isStaticInference: true,
      createdAt: now,
    });
  }

  // Check 4: Unhandled Client-Side Input Length Constraints
  const hasMaxLength = code.includes('maxlength') || code.includes('maxLength');
  if (!hasMaxLength && code.length > 50) {
    bugs.push({
      id: getNextId('INPUT'),
      projectId,
      title: 'Missing Client-Side Maxlength Constraints on Text Inputs',
      severity: 'Low',
      category: 'Validation Gap',
      affectedFeature: 'Input Text Sanitization',
      explanation:
        'Form input elements omit maxlength attributes. Users could potentially paste megabyte-sized text buffers causing UI lag or unexpected backend database string truncation errors (e.g., PostgreSQL varchar(255) exceptions).',
      reproductionSteps: [
        'Generate a 5,000-character string.',
        'Paste string into text input field.',
        'Observe DOM acceptance and submit form.',
      ],
      expectedBehavior:
        'Client inputs should enforce reasonable character limits matching database schema definitions.',
      actualBehavior:
        '(Inferred from static code inspection - unverified on live servers) Input elements lack explicit maxlength limits.',
      suggestedFix:
        'Specify appropriate maxlength attributes (e.g. maxlength="100") on all text input elements.',
      suggestedCodeSnippet: `<input type="text" id="user-name" name="name" maxlength="100" />`,
      isStaticInference: true,
      createdAt: now,
    });
  }

  // Check 5: Sensitive Credential Exposure in Logging or History
  if (
    desc.includes('login') ||
    desc.includes('password') ||
    desc.includes('auth') ||
    code.includes('type="password"')
  ) {
    bugs.push({
      id: getNextId('SEC'),
      projectId,
      title: 'Risk of Cleartext Password Retention in Form Resubmission or Cache',
      severity: 'Medium',
      category: 'Security Concern',
      affectedFeature: 'Password Input Handling',
      explanation:
        'Password fields must ensure autocomplete attributes are strictly governed (autocomplete="current-password" or "new-password") and forms are never submitted via GET method which leaks credentials into browser history and server access logs.',
      reproductionSteps: [
        'Inspect the <form> method attribute.',
        'Inspect password input autocomplete and value attributes.',
        'Verify no debug console.log statements output form values.',
      ],
      expectedBehavior:
        'Form explicitly specifies method="POST", password autocomplete is current-password or off, and credentials are never mirrored in URL query strings.',
      actualBehavior:
        '(Inferred from static code inspection - unverified on live servers) Ensure autocomplete="current-password" is confirmed and no debug logging touches password values.',
      suggestedFix:
        'Ensure autocomplete="current-password" is set and verify in tests that credentials are never transmitted via GET or dumped in client console logs.',
      suggestedCodeSnippet: `<input type="password" id="password" name="password" autocomplete="current-password" required />`,
      isStaticInference: true,
      createdAt: now,
    });
  }

  return bugs;
}

/**
 * Generate readable, copyable, and executable Playwright Python test scripts
 */
export function generatePlaywrightPythonScript(
  payload: GenerateScriptPayload
): GeneratedScript {
  const {
    projectId,
    testCases,
    stagingUrl = 'https://staging.app.example.com',
    targetBrowser = 'Chromium',
    includeHeadless = false,
    takeScreenshots = true,
  } = payload;

  const now = new Date().toISOString();
  const scriptId = `PY-SCRIPT-${Date.now().toString(36).toUpperCase()}`;

  // Format Python test cases
  const pythonTestFunctions = testCases
    .map((tc, index) => {
      const funcName = `test_${tc.id.toLowerCase().replace(/[^a-z0-9]+/g, '_')}_${tc.title
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .slice(0, 40)}`;

      const sanitizedUrl = stagingUrl.endsWith('/')
        ? stagingUrl.slice(0, -1)
        : stagingUrl;

      const stepsComment = tc.steps
        .map((s, i) => `    # Step ${i + 1}: ${s}`)
        .join('\n');

      let actionCode = '';

      if (tc.category === 'Functional') {
        actionCode = `    # Navigate to target page
    page.goto(TARGET_BASE_URL)
    page.wait_for_load_state("networkidle")

    # Locate and interact with primary form fields
    # Note: Replace placeholders with target component locators if different
    email_input = page.get_by_label("Work Email Address").or_(page.locator("input[type='email']"))
    expect(email_input).to_be_visible()
    email_input.fill("qa.testuser@example.com")

    password_input = page.get_by_label("Password").or_(page.locator("input[type='password']"))
    expect(password_input).to_be_visible()
    password_input.fill("ValidPassword123!")

    # Submit form
    submit_btn = page.get_by_role("button", name="Sign in to Workspace").or_(page.locator("button[type='submit']"))
    submit_btn.click()

    # Assert expected outcome
    # ${tc.expectedResult}
    page.wait_for_timeout(1000)
    ${
      takeScreenshots
        ? `page.screenshot(path="artifacts/screenshots/${funcName}_passed.png")`
        : '# Screenshots disabled in config'
    }`;
      } else if (tc.category === 'Validation') {
        actionCode = `    # Navigate to target page
    page.goto(TARGET_BASE_URL)
    page.wait_for_load_state("domcontentloaded")

    # Attempt submission with empty / invalid inputs
    submit_btn = page.locator("button[type='submit']").first
    submit_btn.click()

    # Assert validation error message or required field validation
    # Expected: ${tc.expectedResult}
    error_element = page.locator("[role='alert'], .text-red-500, :invalid").first
    expect(error_element).to_be_visible()
    ${
      takeScreenshots
        ? `page.screenshot(path="artifacts/screenshots/${funcName}_validation.png")`
        : ''
    }`;
      } else if (tc.category === 'Accessibility') {
        actionCode = `    # Navigate to target page
    page.goto(TARGET_BASE_URL)

    # Verify focus sequence via keyboard Tab key
    page.keyboard.press("Tab")
    
    # Assert active element has focus
    active_element = page.evaluate("() => document.activeElement ? document.activeElement.tagName : ''")
    assert active_element in ["INPUT", "BUTTON", "A"], f"Expected interactive element focused, got: {active_element}"

    # Verify form inputs have accessible labels or aria-label attributes
    inputs = page.locator("input:not([type='hidden'])").all()
    for input_elem in inputs:
        has_label = page.evaluate("""
            (el) => {
                const id = el.id;
                const label = id ? document.querySelector('label[for="' + id + '"]') : null;
                const ariaLabel = el.getAttribute('aria-label');
                const ariaLabelledBy = el.getAttribute('aria-labelledby');
                return !!(label || ariaLabel || ariaLabelledBy);
            }
        """, input_elem)
        assert has_label, "Accessibility failure: Input missing associated <label> or aria-label"`;
      } else if (tc.category === 'Security') {
        actionCode = `    # Navigate to target page
    page.goto(TARGET_BASE_URL)

    # Security check: verify password fields are masked
    password_fields = page.locator("input[type='password']").all()
    for pwd in password_fields:
        expect(pwd).to_have_attribute("type", "password")

    # Verify XSS sanitization does not execute script tags
    test_xss_input = "<script>window.__xss_detected=true</script>"
    first_input = page.locator("input[type='text'], input[type='email']").first
    if first_input.count() > 0:
        first_input.fill(test_xss_input)
        xss_executed = page.evaluate("() => window.__xss_detected === true")
        assert not xss_executed, "Security vulnerability: Script tag executed in client DOM"`;
      } else {
        actionCode = `    # Navigate to target page
    page.goto(TARGET_BASE_URL)
    page.wait_for_load_state("networkidle")

    # Execute test scenario: ${tc.title}
    # Objective: ${tc.objective}
    # Test Data: ${tc.testData}
    page.wait_for_timeout(500)
    ${
      takeScreenshots
        ? `page.screenshot(path="artifacts/screenshots/${funcName}.png")`
        : ''
    }`;
      }

      return `def ${funcName}(page: Page):
    """
    Test Case ID: ${tc.id}
    Title: ${tc.title}
    Category: ${tc.category} | Priority: ${tc.priority}
    Objective: ${tc.objective}
    """
${stepsComment}
${actionCode}
`;
    })
    .join('\n\n');

  const browserCode =
    targetBrowser === 'Firefox'
      ? 'p.firefox'
      : targetBrowser === 'WebKit' || targetBrowser === 'Mobile Safari'
      ? 'p.webkit'
      : 'p.chromium';

  const fullPythonCode = `"""
Playwright Python Automated Test Suite
Generated by TestGenius AI — Automated QA Testing Engine
Generated on: ${new Date().toUTCString()}
Target Browser: ${targetBrowser} | Framework: Playwright (Python) + pytest

Setup & Execution Instructions:
1. Ensure Python 3.9+ is installed.
2. Install Playwright and pytest dependencies:
   pip install pytest pytest-playwright playwright
3. Download browser binaries:
   playwright install ${targetBrowser.toLowerCase().includes('firefox') ? 'firefox' : targetBrowser.toLowerCase().includes('webkit') ? 'webkit' : 'chromium'}
4. Run this test suite:
   pytest -v --headed ${scriptId.toLowerCase()}.py
5. Run in headless mode:
   pytest -v ${scriptId.toLowerCase()}.py
"""

import os
import pytest
from playwright.sync_api import sync_playwright, Page, expect

# Staging Environment Configuration
# DISCLAIMER: Generated scripts use placeholders for non-public staging endpoints and test credentials.
TARGET_BASE_URL = os.getenv("STAGING_APP_URL", "${stagingUrl}")

@pytest.fixture(scope="session")
def browser_context():
    """
    Session-scoped browser initialization fixture.
    Configures browser context with accessibility and performance options.
    """
    os.makedirs("artifacts/screenshots", exist_ok=True)
    with sync_playwright() as p:
        browser = ${browserCode}.launch(
            headless=${includeHeadless ? 'True' : 'False'},
            slow_mo=100, # Added for human review; remove or reduce for CI/CD runs
        )
        context = browser.new_context(
            viewport={"width": 1280, "height": 720},
            ignore_https_errors=True, # Useful for self-signed staging certificates
            user_agent="Mozilla/5.0 (Playwright TestGenius-AI Automated Suite)"
        )
        yield context
        context.close()
        browser.close()

@pytest.fixture(scope="function")
def page(browser_context) -> Page:
    """
    Function-scoped page fixture for test isolation.
    """
    new_page = browser_context.new_page()
    yield new_page
    new_page.close()

# ==============================================================================
# TEST SUITE IMPLEMENTATION
# ==============================================================================

${pythonTestFunctions}

if __name__ == "__main__":
    # Allows direct execution: python <filename>.py
    pytest.main(["-v", "-s", __file__])
`;

  return {
    id: scriptId,
    projectId,
    title: `Playwright Python Suite (${testCases.length} Test Cases)`,
    testCaseIds: testCases.map((tc) => tc.id),
    framework: 'playwright-python',
    pythonCode: fullPythonCode,
    assumptions: [
      `Assumes staging base URL is accessible at: ${stagingUrl}`,
      'Locators prioritize accessible roles (page.get_by_role, page.get_by_label) with CSS selectors as fallbacks',
      'Assumes test user credentials exist in the target database or mock environment',
      'Screenshots are preserved in ./artifacts/screenshots/ directory on test run',
    ],
    setupInstructions:
      'pip install pytest pytest-playwright playwright && playwright install && pytest -v --headed <filename>.py',
    targetBrowser,
    createdAt: now,
  };
}
